void buildAcceptanceCriteriaListChildren(som::SomMetaNode& parent, std::vector<std::string>& stack) {
  {
    auto n = std::make_unique<som::SomMetaNode>();
    (*n).className = "AcceptanceCriteriaList";
    (*n).memberName = "content";
    (*n).kind = som::kSomMetaKindContent;
    (*n).typeName = "String";
    (*n).hasSerializationOrder = true;
    (*n).serializationOrder = 0;
    (*n).contentType = som::SomContentTypeMeta{"text", ""};
    (*n).contentHelp = "Formal acceptance criteria that must be met for project sign-off.\nCovers functional, non-functional, documentation, and training criteria.\nEach criterion must be:\n- Objectively verifiable (measurable or binary pass/fail)\n- Traceable to a requirement or deliverable\n- Assigned a verification method and responsible verifier\n- Categorized by type and priority\n";
    parent.addChild(std::move(n));
  }
  {
    auto ln = std::make_unique<som::SomMetaNode>();
    (*ln).className = "AcceptanceCriteriaList";
    (*ln).memberName = "items";
    (*ln).sectionId = "DACEN-ITEM-LST";
    (*ln).sectionIdPattern = "DACEN-ITEM-xxx";
    (*ln).kind = som::kSomMetaKindList;
    (*ln).typeName = "DeliveryAcceptanceCriterionEntry";
    (*ln).hasSerializationOrder = true;
    (*ln).serializationOrder = 1;
    (*ln).contentHelp = "Add one entry per acceptance criterion.";
    (*ln).docComment = "Contains 0+× DeliveryAcceptanceCriterion.";
    (*ln).extra.push_back(som::SomMetaExtra{"StandardReferences", som::jsonParse("{\"standards\":[\"ISO/IEC/IEEE 29119 2022 — the software testing standard defines the acceptance-criteria and test-item structures\",\"IEEE 829-2008 — the standard for software and system test documentation defines the list of acceptance criteria in the acceptance-test plan\"],\"connotation\":\"Lists the individual acceptance criteria that delivered work must satisfy.\"}", nullptr)});
    ln->elementNode = metaCx("DeliveryAcceptanceCriterionEntry", stack,
      [](som::SomMetaNode& n) {
        n.className = "DeliveryAcceptanceCriterionEntry";
        n.classSectionId = "DACEN";
        n.kind = som::kSomMetaKindComplex;
        n.typeName = "DeliveryAcceptanceCriterionEntry";
        n.docComment = "An acceptance criterion entry (form).\n\nA single criterion that must be met for formal project acceptance.\nAligned with IEEE 830 acceptance criteria structure and ISTQB\nacceptance test design.";
        n.classDocComment = "An acceptance criterion entry (form).\n\nA single criterion that must be met for formal project acceptance.\nAligned with IEEE 830 acceptance criteria structure and ISTQB\nacceptance test design.";
      },
      buildDeliveryAcceptanceCriterionEntryChildren);
    parent.addChild(std::move(ln));
  }
}

